1729	/**
1730	 * Updates an existing knowledge insight identified by its numeric ID.
1731	 *
1732	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
1733	 * for non-integer, zero, or floating-point strings). Validates the request body
1734	 * via `KnowledgeUpdateBodySchema` (throws VALIDATION_ERROR for unknown fields or
1735	 * type mismatches). Extracts `scope` and `project_slug` discriminator fields to
1736	 * scope the update to the correct store.
1737	 *
1738	 * `superseded_by: null` in the body is mapped to `undefined` so the field is
1739	 * cleared (removed) on the stored insight.
1740	 *
1741	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
1742	 *
1743	 * @param ledgerRoot  Absolute path to the central ledger root.
1744	 * @param rawId       Raw ID string from the URL parameter (e.g. "42").
1745	 * @param body        Parsed request body (any shape — validated here).
1746	 * @returns The updated Insight.
1747	 */
1748	export async function handleUpdateKnowledge(
1749	  ledgerRoot: string,
1750	  rawId: string,
1751	  body: unknown
1752	): Promise<Insight> {
1753	  const id = parseKnowledgeId(rawId);
1754	
1755	  const parseResult = KnowledgeUpdateBodySchema.safeParse(body);
1756	  if (!parseResult.success) {
1757	    validationError('Invalid knowledge update body.', parseResult.error.issues);
1758	  }
1759	
1760	  const { scope, project_slug, superseded_by, ...rest } = parseResult.data;
1761	
1762	  // Map superseded_by: null → undefined so the field is cleared on the stored insight.
1763	  const updates: Parameters<KnowledgeStoreManager['updateInsight']>[1] = {
1764	    ...rest,
1765	    ...(superseded_by === null ? { superseded_by: undefined } : superseded_by !== undefined ? { superseded_by } : {}),
1766	  };
1767	
1768	  const manager = new KnowledgeStoreManager(ledgerRoot);
1769	
1770	  try {
1771	    return await manager.updateInsight(id, updates, { scope, project_slug });
1772	  } catch (err) {
1773	    const msg = err instanceof Error ? err.message : String(err);
1774	    if (msg.includes('not found')) {
1775	      throw new ApiError('NOT_FOUND', 'Insight not found.');
1776	    }
1777	    throw err;
1778	  }
1779	}
