1785	/**
1786	 * Deletes an existing knowledge insight identified by its numeric ID.
1787	 *
1788	 * Validates the raw ID string via `parseKnowledgeId` (throws VALIDATION_ERROR
1789	 * for non-integer, zero, or floating-point strings). Requires `scope` as a
1790	 * query parameter; when `scope === 'project'`, `project_slug` is also required
1791	 * (throws VALIDATION_ERROR if absent). Scopes the deletion to the correct store
1792	 * to prevent accidental cross-scope deletion when the same numeric ID exists in
1793	 * multiple stores.
1794	 *
1795	 * Throws NOT_FOUND when no insight with the given ID exists in the specified scope.
1796	 *
1797	 * @param ledgerRoot   Absolute path to the central ledger root.
1798	 * @param rawId        Raw ID string from the URL parameter (e.g. "42").
1799	 * @param scope        Required scope query parameter ('global' or 'project').
1800	 * @param project_slug Required when scope is 'project'; the project slug.
1801	 * @returns `null` — consistent with other delete handlers.
1802	 */
1803	export async function handleDeleteKnowledge(
1804	  ledgerRoot: string,
1805	  rawId: string,
1806	  scope: string | undefined,
1807	  project_slug?: string
1808	): Promise<null> {
1809	  const id = parseKnowledgeId(rawId);
1810	
1811	  // Validate scope — required and must be a recognised InsightScope value.
1812	  const scopeResult = InsightScope.safeParse(scope);
1813	  if (!scopeResult.success) {
1814	    validationError('scope query parameter is required and must be "global" or "project".');
1815	  }
1816	  const validatedScope = scopeResult.data;
1817	
1818	  // project_slug is required when scope === 'project'.
1819	  if (validatedScope === 'project' && !project_slug) {
1820	    validationError('project_slug query parameter is required when scope is "project".');
1821	  }
1822	
1823	  const manager = new KnowledgeStoreManager(ledgerRoot);
1824	
1825	  try {
1826	    await manager.deleteInsight(id, { scope: validatedScope, project_slug });
1827	  } catch (err) {
1828	    const msg = err instanceof Error ? err.message : String(err);
1829	    if (msg.includes('not found')) {
1830	      throw new ApiError('NOT_FOUND', 'Insight not found.');
1831	    }
1832	    throw err;
1833	  }
1834	
1835	  return null;
1836	}
